3	/** Identifies which operation surface produced a validation failure. */
4	export type OperationKind = 'query' | 'command';
5	
6	/**
7	 * Describes the operation and validation phase associated with a schema failure.
8	 */
9	export type ValidationMeta = {
10	  kind: OperationKind;
11	  serviceId: string;
12	  name: string;
13	  phase: 'input' | 'output';
14	  issues: ReadonlyArray<StandardSchemaV1.Issue>;
15	};
16	
17	/**
18	 * Formats a schema issue path into the field notation shown in validation errors.
19	 *
20	 * Examples:
21	 * - `['foo']` -> `foo`
22	 * - `['items', 0, 'id']` -> `items[0].id`
23	 */
24	function formatIssuePath(path?: readonly (PropertyKey | StandardSchemaV1.PathSegment)[]): string {
25	  if (!path?.length) {
26	    return '';
27	  }
28	
29	  return path
30	    .map((segment) => {
31	      const key =
32	        typeof segment === 'object' && segment !== null && 'key' in segment ? segment.key : segment;
33	
34	      return typeof key === 'number' ? `[${key}]` : `.${String(key)}`;
35	    })
36	    .join('')
37	    .replace(/^\./, '');
38	}
39	
40	/**
41	 * Converts schema issues into the newline-separated detail block appended to user-facing errors.
42	 */
43	export function formatIssues(issues: ReadonlyArray<StandardSchemaV1.Issue>): string {
44	  return issues
45	    .map((issue) => {
46	      const path = formatIssuePath(issue.path);
47	      return path === '' ? issue.message : `${path}: ${issue.message}`;
48	    })
49	    .join('\n');
50	}
