15	describe('static builds', () => {
16	  describe('buildStaticFiles', () => {
17	    it('runs preload from initial state for each input and deep-merges by path', async () => {
18	      await expect(buildStaticFiles([awaitedPreloadValueServiceDef])).resolves.toEqual({
19	        'test/awaited-preload-value.json': {
20	          'entry-a': 'preloaded',
